@import url('https://fonts.googleapis.com/css2?family=Space+Mono:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600;700&display=swap');

/* Teenage Engineering DNA — light gray plastic, orange accents, tiny mono uppercase labels */
.theme-teenage-engineering-dna {
  --bg: oklch(0.93 0.002 250);
  --surface: oklch(0.965 0.002 250);
  --surface-2: oklch(0.885 0.003 250);
  --fg: oklch(0.2 0.003 250);
  --fg-muted: oklch(0.5 0.004 250);
  --accent: oklch(0.659 0.195 38.3);
  --accent-fg: oklch(0.000 0 0);
  --accent-2: oklch(0.815 0.166 79.8);
  --line: oklch(0.72 0.004 250);
  --success: oklch(0.62 0.14 150);
  --warning: oklch(0.78 0.16 85);
  --danger: oklch(0.58 0.22 27);

  --radius: 0px;
  --radius-sm: 0px;
  --radius-lg: 0px;
  --radius-pill: 0px;

  --shadow-1: inset 0 1px 0 oklch(1 0 0 / 80%), 0 1px 0 oklch(0 0 0 / 10%);
  --shadow-2: inset 0 1px 0 oklch(1 0 0 / 80%), 0 2px 4px oklch(0 0 0 / 12%);
  --shadow-3: inset 0 1px 0 oklch(1 0 0 / 80%), 0 8px 20px -8px oklch(0 0 0 / 22%);
  --glow: 0 0 0 2px var(--accent);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Space Mono", ui-monospace, monospace;
  --font-body: "Space Mono", ui-monospace, monospace;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;

  --tracking-display: -0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.14em;

  background-color: var(--bg);
  background-image:
    linear-gradient(oklch(0 0 0 / 3%) 1px, transparent 1px),
    linear-gradient(90deg, oklch(0 0 0 / 3%) 1px, transparent 1px);
  background-size: 24px 24px;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-teenage-engineering-dna h1,
.theme-teenage-engineering-dna h2,
.theme-teenage-engineering-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 600;
}

.theme-teenage-engineering-dna label,
.theme-teenage-engineering-dna th {
  font-family: var(--font-mono);
  text-transform: var(--label-transform);
  letter-spacing: var(--label-tracking);
  font-size: 0.7rem;
}

/* signature */
.theme-teenage-engineering-dna { background-image: linear-gradient(180deg, oklch(1 0 0 / 40%), transparent 200px); }
.theme-teenage-engineering-dna button { text-transform: uppercase; letter-spacing: 0.14em; font-size: 11px; }
.theme-teenage-engineering-dna h2::before { content: "● "; color: var(--accent); font-size: 0.6em; vertical-align: middle; }

/* depth */
.theme-teenage-engineering-dna button { box-shadow: inset 0 1px 0 oklch(1 0 0 / 80%), inset 0 -2px 0 oklch(0 0 0 / 12%), 0 1px 0 oklch(0 0 0 / 15%); transition: none; }
.theme-teenage-engineering-dna button:active { transform: translateY(1px); box-shadow: inset 0 1px 3px oklch(0 0 0 / 25%); }
.theme-teenage-engineering-dna table { border-collapse: collapse; }
.theme-teenage-engineering-dna thead th { border-top: 1px solid var(--fg); border-bottom: 1px solid var(--fg); background: transparent; }
.theme-teenage-engineering-dna td { border-bottom: 1px solid var(--line); font-variant-numeric: tabular-nums; font-size: 0.8125rem; }
.theme-teenage-engineering-dna tbody tr:hover { background: oklch(1 0 0 / 55%); }
.theme-teenage-engineering-dna input, .theme-teenage-engineering-dna select, .theme-teenage-engineering-dna textarea { font-family: var(--font-mono); background: oklch(0.97 0.002 250); border: 1px solid var(--line); border-radius: 0; box-shadow: inset 0 1px 2px oklch(0 0 0 / 10%); }
.theme-teenage-engineering-dna input:focus-visible, .theme-teenage-engineering-dna select:focus-visible, .theme-teenage-engineering-dna textarea:focus-visible { outline: none; border-color: var(--fg); box-shadow: inset 0 1px 2px oklch(0 0 0 / 10%), 0 0 0 2px var(--accent); }
.theme-teenage-engineering-dna kbd { font-family: var(--font-mono); font-size: 0.7rem; text-transform: uppercase; background: var(--surface); border: 1px solid var(--line); border-radius: 0; padding: 0.1em 0.5em; box-shadow: 0 2px 0 var(--line); }
.theme-teenage-engineering-dna a { color: var(--fg); text-decoration: underline; text-decoration-style: dotted; text-underline-offset: 3px; }
.theme-teenage-engineering-dna a:hover { color: var(--accent); text-decoration-style: solid; }
.theme-teenage-engineering-dna ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-teenage-engineering-dna ::-webkit-scrollbar { width: 12px; height: 12px; }
.theme-teenage-engineering-dna ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-teenage-engineering-dna ::-webkit-scrollbar-thumb { background: oklch(0.55 0.004 250); border-radius: 0; border: 2px solid var(--surface-2); }
.theme-teenage-engineering-dna .label-caps { font-family: var(--font-mono); font-size: 0.65rem; }
.theme-teenage-engineering-dna .themed-border { border-color: var(--fg); }

/* alt mode: OP-1 field black edition — same plastic, charcoal molding */
.theme-teenage-engineering-dna.alt-mode {
  --bg: oklch(0.220 0.003 250);
  --surface: oklch(0.270 0.003 250);
  --surface-2: oklch(0.320 0.004 250);
  --fg: oklch(0.920 0.002 250);
  --fg-muted: oklch(0.650 0.004 250);
  --line: oklch(0.420 0.004 250);
  --shadow-1: inset 0 1px 0 oklch(1 0 0 / 10%), 0 1px 0 oklch(0 0 0 / 40%);
  --shadow-2: inset 0 1px 0 oklch(1 0 0 / 10%), 0 2px 4px oklch(0 0 0 / 45%);
  --shadow-3: inset 0 1px 0 oklch(1 0 0 / 10%), 0 8px 20px -8px oklch(0 0 0 / 60%);
  background-image:
    linear-gradient(oklch(1 0 0 / 4%) 1px, transparent 1px),
    linear-gradient(90deg, oklch(1 0 0 / 4%) 1px, transparent 1px);
  background-size: 24px 24px;
}
.theme-teenage-engineering-dna.alt-mode button { box-shadow: inset 0 1px 0 oklch(1 0 0 / 15%), inset 0 -2px 0 oklch(0 0 0 / 35%), 0 1px 0 oklch(0 0 0 / 45%); }
.theme-teenage-engineering-dna.alt-mode input, .theme-teenage-engineering-dna.alt-mode select, .theme-teenage-engineering-dna.alt-mode textarea { background: oklch(0.18 0.003 250); box-shadow: inset 0 1px 2px oklch(0 0 0 / 40%); }
.theme-teenage-engineering-dna.alt-mode tbody tr:hover { background: oklch(1 0 0 / 8%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
